class Solution {
    private int[] map = new int[26];
    private boolean[] used = new boolean[10];
    private boolean[] leading = new boolean[26];
    private String[] words;
    private String result;
    private int maxLen;
    private int wordsCount;

    public boolean isSolvable(String[] words, String result) {
        this.words = words;
        this.result = result;
        this.wordsCount = words.length;
        Arrays.fill(map, -1);
        Arrays.fill(used, false);
        Arrays.fill(leading, false);

        // mark leading letters (cannot be zero if length > 1)
        for (String w : words) {
            if (w.length() > 1) {
                leading[w.charAt(0) - 'A'] = true;
            }
        }
        if (result.length() > 1) {
            leading[result.charAt(0) - 'A'] = true;
        }

        // quick impossible check: any word longer than result -> impossible
        maxLen = result.length();
        for (String w : words) {
            if (w.length() > maxLen) return false;
        }

        return dfs(0, 0, 0);
    }

    // pos: current column from least significant (0-based)
    // idx: current word index being processed (0..wordsCount)
    // sum: accumulated sum for this column including carry from previous columns
    private boolean dfs(int pos, int idx, int sum) {
        if (pos == maxLen) {
            // all columns processed; sum should be zero (no leftover carry)
            return sum == 0;
        }
        if (idx < wordsCount) {
            String w = words[idx];
            int len = w.length();
            if (pos >= len) {
                // this word has no char at this column, treat as 0
                return dfs(pos, idx + 1, sum);
            } else {
                int li = w.charAt(len - 1 - pos) - 'A';
                if (map[li] != -1) {
                    return dfs(pos, idx + 1, sum + map[li]);
                } else {
                    for (int d = 0; d <= 9; d++) {
                        if (used[d]) continue;
                        if (d == 0 && leading[li]) continue;
                        // assign
                        map[li] = d;
                        used[d] = true;
                        if (dfs(pos, idx + 1, sum + d)) return true;
                        // backtrack
                        map[li] = -1;
                        used[d] = false;
                    }
                    return false;
                }
            }
        } else {
            // process result char for this column
            int total = sum;
            int expected = total % 10;
            int nextSum = total / 10;
            int len = result.length();
            int li = result.charAt(len - 1 - pos) - 'A';
            if (map[li] != -1) {
                if (map[li] != expected) return false;
                return dfs(pos + 1, 0, nextSum);
            } else {
                if (used[expected]) return false;
                if (expected == 0 && leading[li]) return false;
                map[li] = expected;
                used[expected] = true;
                boolean res = dfs(pos + 1, 0, nextSum);
                map[li] = -1;
                used[expected] = false;
                return res;
            }
        }
    }
}

